    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            g[i][j] = 0;
        }
    }
    for (int i = 1; i <= m; i++) {
        int x, y;
        cin >> x >> y;
        g[x][y] = g[y][x] = 1;
    }
    BFS();
    if (dis[n][1] == 0) {
        cout << -1 << endl;
    } else {
        printPath();
    }
    return 0;
}

