    cin >> n >> u >> v;
    u--, v--;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    dfs(u, -1, 0);
    vector<int> dist_from_u(n);
    for (int i = 0; i < n; i++) dist_from_u[i] = depth[i];
    for (int i = 0; i < n; i++) depth[i] = 0;
    dfs(v, -1, 0);
    vector<int> dist_from_v(n);
    for (int i = 0; i < n; i++) dist_from_v[i] = depth[i];

    int ans = n;
    for (int i = 0; i < n; i++) {
        ans = min(ans, (dist_from_u[i] + dist_from_v[i]));
    }
