constexpr ll mod = 998244353;

ll powerMod(ll a, ll b, ll mod) {
    if (b == 0) return 1;
    ll res = powerMod(a, b / 2, mod);
    if (b % 2 == 0) return res * res % mod;
    else return res * res % mod * a % mod;
}

