    for (int i = 0; i < m; i++) {
        int t;
        cin >> t;
        c[t] = i + 1;
    }
    llIDTH = __gcd(n, m);
    ll lcm = 1LL * n * m / __gcd(n, m);
    for (int i = 0; i < n; i++) {
        if (!c[a[i]]) continue;
        ll t = c[a[i]] - 1 - i;
        t = (t % m + m) % m;
        ll x = i;
        ll y = t;
        while (x < lcm) {
            b[x] = 1;
            x += n;
            y += n;
