    for (int i = 0; i < lcm; i++) if (!b[i]) cnt++;
    ll tmp = k / (lcm - cnt);
    ll ans = tmp * lcm;
    k -= tmp * (lcm - cnt);
    for (int i = 0; i < lcm; i++) {
        if (k == 0) break;
        if (!b[i]) k--;
        ans++;
    }
    cout << ans << endl;
