                    for (int right = left + 1; right <= m; ++right) {
                        int sz = right - left + 1;

                        long long curr = 0;
                        for (int up = 0; up <= t - l; ++up) {
                            int remUp = t - l - up;
                            long long waysUp = 1;
                            for (int i = 0; i < up; ++i) {
                                waysUp = waysUp * (sz - i);
                                waysUp %= mod;
                            }
                            for (int i = 1; i <= remUp; ++i) {
                                waysUp = waysUp * (sz - up - i + 1);
                                waysUp %= mod;
                            }

                            long long waysDown = 1;
                            for (int i = 0; i < r - t; ++i) {
                                waysDown = waysDown * (sz - up - i);
                                waysDown %= mod;
                            }

                            curr += waysUp * waysDown;
                            curr %= mod;
                        }

                        ans += curr;
                        ans %= mod;
                    }
                }
            }
        }
    }

    cout << ans << '\n';

    return 0;
}

