        adjacencyList[p].push_back(i);
    }

    for (int i = 0; i < n; i++) {
        cin >> limit[i];
    }

    dfs(0);

    for (int i = 0; i < m; i++) {
        int query;
        cin >> query;

        int vertex = abs(query) - 1;
        onVacation[vertex] = !onVacation[vertex];

        if (onVacation[vertex]) {
            update(vertex);
        } else {
            update(parent[vertex]);
        }

        int displeased = 0;
        for (int j = 0; j < n; j++) {
            if (subordinates[j] > limit[j] && !onVacation[j]) {
                displeased++;
            }
        }

        cout << displeased << " ";
    }

    return 0;
}

