struct DSU {
    int fa[N];
    void init(int n) {
        for (int i = 1; i <= n; i++) fa[i] = i;
    }
    int find(int a) {
        return a == fa[a] ? a : fa[a] = find(fa[a]);
    }
    void merge(int a, int b) {
        int x = find(a);
        int y = find(b);
        if (x != y) fa[x] = y;
    }
};

int n, m;
set<pair<int, int>> e;
vector<pair<int, int>> a;
