    dsu.init(n);
    for (auto [u, v] : e) {
        dsu.merge(u, v);
        d[u]++;
    }
    for (int i = 1; i <= n; i++) {
        if (dsu.find(i) != 1) ans.emplace_back(i, 1);
        if (d[i] > 1) {
            cout << "NO\n";
