    vector<long long> fac(n);
    fac[0] = 1;
    for (int i = 1; i < n; ++i) fac[i] = fac[i - 1] * i % mod;
    vector<int> cnt(n - 1);
    for (int i = 0; i < n - 1; ++i) cnt[i] = x[i + 1] - x[i];
    long long ans = 0;
    for (int i = 0; i < n - 1; ++i) {
        long long tot = 0;
        for (int j = 0; j < i + 1; ++j) tot = (tot + fac[i] * inv(fac[j]) % mod * inv(fac[i - j]) % mod * (i - j)) % mod;
        ans = (ans + cnt[i] * tot) % mod;
    }
    cout << ans << endl;
    return 0;
}

