typedef long long ll;

ll n, m, k;
vector<string> words;

ll dfs(string s, ll len) {
    if (len == m) {
        return k > 0;
    }
    k--;
    for (string word : words) {
        if (len + word.length() <= m && k > 0) {
            s += word;
            ll ret = dfs(s, len + word.length());
            if (ret > 0) return ret;
            s = s.substr(0, s.length() - word.length());
            k -= ret;
        }
    }
    return k;
}

