#include <bits/stdc++.h>

using namespace std;

const double eps = 1e-8;

struct Point {
    double x, y;
};

bool operator<(const Point &a, const Point &b) {
    return a.x < b.x;
}

double dist(const Point &a, const Point &b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

double calc(double a, double p, double q, double x) {
    return a * (x - p) * (x - p) + q;
}

int main() {
    int W, H, N;
    cin >> W >> H >> N;

    vector<tuple<double, double, double>> peaks(N);
    for (auto &[a, p, q] : peaks) {
        cin >> a >> p >> q;
    }

    vector<Point> boundary;
    for (int i = 0; i < N; i++) {
        auto [a, p, q] = peaks[i];
        double x = 0;
        while (x <= W) {
            double y = calc(a, p, q, x);
            if (y <= H) {
                boundary.push_back({x, y});
            }
            x += 1;
        }
    }

    for (int i = 0; i < N; i++) {
        auto [a, p, q] = peaks[i];
        double x = W;
        while (x >= 0) {
            double y = calc(a, p, q, x);
            if (y <= H) {
                boundary.push_back({x, y});
            }
            x -= 1;
        }
    }

    sort(boundary.begin(), boundary.end());

    vector<Point> convex_hull;
    for (const auto &p : boundary) {
        while (convex_hull.size() >= 2) {
            const auto &q = convex_hull[convex_hull.size() - 1];
            const auto &r = convex_hull[convex_hull.size() - 2];
            if ((q.x - r.x) * (p.y - r.y) - (q.y - r.y) * (p.x - r.x) >= 0) {
                convex_hull.pop_back();
            } else {
                break;
            }
        }
        convex_hull.push_back(p);
    }

    double ans = 0;
    for (int i = 0; i < convex_hull.size() - 1; i++) {
        ans += dist(convex_hull[i], convex_hull[i + 1]);
    }

    cout << fixed << setprecision(15) << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Edge {
    int to, cost;
};

struct Event {
    int a, b, c;
};

void solve() {
    int N, M, E, S, T, R;
    cin >> N >> M >> E >> S >> T >> R;

    vector<vector<Edge>> G(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        G[a].push_back({b, 1});
        G[b].push_back({a, 1});
    }

    vector<Event> events(E);
    for (int i = 0; i < E; i++) {
        cin >> events[i].a >> events[i].b >> events[i].c;
    }

    vector<vector<vector<int>>> dist(N, vector<vector<int>>(1 << E, vector<int>(R + 1, INF)));
    vector<vector<vector<bool>>> used(N, vector<vector<bool>>(1 << E, vector<bool>(R + 1, false)));
    queue<tuple<int, int, int, int>> Q;

    dist[S][0][0] = 0;
    Q.emplace(S, 0, 0, 0);

    while (!Q.empty()) {
        int v, mask, cost, day;
        tie(v, mask, cost, day) = Q.front();
        Q.pop();

        if (used[v][mask][day]) continue;
        used[v][mask][day] = true;

        for (const auto& e : G[v]) {
            if (dist[e.to][mask][day + 1] > dist[v][mask][day] + e.cost) {
                dist[e.to][mask][day + 1] = dist[v][mask][day] + e.cost;
                Q.emplace(e.to, mask, dist[e.to][mask][day + 1], day + 1);
            }
        }

        for (const auto& event : events) {
            if (event.c == v && (mask & (1 << &event - &events[0])) == 0) {
                if (dist[event.a][mask | (1 << &event - &events[0])][day] > dist[v][mask][day]) {
                    dist[event.a][mask | (1 << &event - &events[0])][day] = dist[v][mask][day];
                    Q.emplace(event.a, mask | (1 << &event - &events[0]), dist[event.a][mask | (1 << &event - &events[0])][day], day);
                }
                if (dist[event.b][mask | (1 << &event - &events[0])][day] > dist[v][mask][day]) {
                    dist[event.b][mask | (1 << &event - &events[0])][day] = dist[v][mask][day];
                    Q.emplace(event.b, mask | (1 << &event - &events[0]), dist[event.b][mask | (1 << &event - &events[0])][day], day);
                }
            }
        }

        if (day <= R && dist[S][mask][0] > dist[v][mask][day] + 1) {
            dist[S][mask][0] = dist[v][mask][day] + 1;
            Q.emplace(S, mask, dist[S][mask][0], 0);
        }
    }

    int ans = INF;
    for (int i = 0; i < (1 << E); i++) {
        for (int j = 0; j <= R; j++) {
            ans = min(ans, dist[T][i][j] + (j + (i > 0)) / (R + 1));
        }
    }

    cout << (ans == INF ? -1 : ans) << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    solve();
    return 0;
}

