}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> k;
    for (int i = 1; i <= n; i++) {
        cin >> l[i] >> r[i];
    }

    int ans = 1e9;
    vector<int> pos;

    do {
        memset(del, 0, sizeof(del));
        for (int i = 1; i <= n; i++) {
            if (!del[i]) {
                for (int j = l[i]; j <= r[i]; j++) {
                    cnt[j]++;
                }
            }
        }

        int badPoint = 0;
        for (int i = 1; i <= 200; i++) {
            if (cnt[i] > k) {
                badPoint++;
            }
        }

        for (int i = 1; i <= 200; i++) {
            cnt[i] = 0;
        }

        if (badPoint == 0) {
            int cntDel = 0;
            for (int i = 1; i <= n; i++) {
                if (del[i]) {
                    cntDel++;
                }
            }
            if (cntDel < ans) {
                ans = cntDel;
                pos.clear();
                for (int i = 1; i <= n; i++) {
                    if (del[i]) {
                        pos.push_back(i);
                    }
                }
            }
        } else {
            int minIdx = -1, maxCnt = -1;
            for (int i = 1; i <= n; i++) {
                if (del[i]) {
                    continue;
                }
                int curCnt = 0;
                memset(cnt, 0, sizeof(cnt));
                for (int j = 1; j <= n; j++) {
                    if (del[j] || j == i) {
                        continue;
                    }
                    for (int t = l[j]; t <= r[j]; t++) {
                        cnt[t]++;
                    }
                }
                for (int j = l[i]; j <= r[i]; j++) {
                    cnt[j]++;
                }
                for (int j = 1; j <= 200; j++) {
                    if (cnt[j] > k) {
                        curCnt++;
                    }
                }
                if (curCnt < badPoint) {
                    badPoint = curCnt;
                    minIdx = i;
                }
            }
            del[minIdx] = 1;
        }
    } while (next_permutation(del + 1, del + n + 1));

    cout << ans << '\n';
    for (int x : pos) {
        cout << x << " ";
    }
    return 0;
}

