    // read document id
    std::getline(std::cin, line);

    // read document name
    std::getline(std::cin, line);

    // read document text
    while (std::getline(std::cin, line)) {
        text += line + " ";
    }

    int classification = classifyDocument(text);
    std::cout << classification << std::endl;

    return 0;
}

