    cout << "\n";
}

bool can_sum(int a, int b) {
    vector<int> digits_a(10, 1);
    vector<int> digits_b(10, 1);
    for (; a; a /= 10) {
        digits_a[a % 10] = 0;
    }
    for (; b; b /= 10) {
        digits_b[b % 10] = 0;
    }
    for (int i = 0; i < 10; ++i) {
        if (!digits_a[i] && !digits_b[i]) return false;
    }
    return true;
}

