ll modexp(ll x, ll n) {
    if (n == 0) {
        return 1;
    } else if (n % 2 == 0) {
        return (modexp((x * x) % mod, (n / 2)) % mod);
    } else {
        return ((x * modexp((x * x) % mod, ((n - 1) / 2))) % mod);
    }
}

ll power(ll x, ll n) {
    if (n == 0)
        return 1;
    else if (n % 2 == 0)
        return (power((x * x), (n / 2)));
    else
        return (x * power((x * x), ((n - 1) / 2)));
}

ll gcd(ll a, ll b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll mul(ll x, ll y) {
