const int MOD = 1e9 + 7;

int countWaysToSeparate(const std::string& t, const std::vector<std::string>& S) {
    int n = t.size();
    std::vector<int> dp(n + 1);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (const std::string& s : S) {
            int len = s.size();
            if (i >= len && t.substr(i - len, len) == s) {
                dp[i] = (dp[i] + dp[i - len]) % MOD;
            }
        }
    }
    return dp[n];
}

