    for(int i = 0; i < l; ++i) c[n] += 1;
    for (int i = n - 1; i >= 0; --i) {
        while(c[i] && vt[i].back().second < sum) {
            c[i]--;
            c[i + 1]++;
            sum = 0;
        }
        sum += dist[i + 1];
    }
    int j = 0;
    ll kek = 0;
    for(int i = 1; i <= n; ++i) {
        for(int k = 0; k < vt[i].size(); ++k) {
            int x = vt[i][k].first;
